import React, { useEffect, useRef } from "react";
import Menu from "./Menu";

const TopBar = () => {
  const widgetRef = useRef(null);

  useEffect(() => {
    // 1. Pehle check karo ki container hai ya nahi
    if (!widgetRef.current) return;

    // 2. Purana content saaf karo
    widgetRef.current.innerHTML = "";

    // 3. Script load logic
    const script = document.createElement("script");
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-tickers.js";
    script.async = true;
    script.type = "text/javascript";

    // Ye line important hai error hatane ke liye
    script.crossOrigin = "anonymous"; 

    script.innerHTML = JSON.stringify({
      "symbols": [
        { "proName": "FOREXCOM:NSXUSD", "title": "NIFTY 50" },
        { "proName": "INDEX:SENSEX", "title": "SENSEX" }
      ],
      "colorTheme": "light",
      "isTransparent": true,
      "showSymbolLogo": false,
      "locale": "in"
    });

    // Error Handling: Agar script load na ho paye toh console block na ho
    script.onerror = () => console.log("TradingView script failed to load, but it's okay.");

    widgetRef.current.appendChild(script);

    return () => {
      if (widgetRef.current) widgetRef.current.innerHTML = "";
    };
  }, []);

  return (
    <div className="topbar-container" style={{ display: "flex", justifyContent: "space-between", alignItems: "center", height: "60px", padding: "0 20px" }}>
      {/* Humne 'useRef' ka use kiya hai 'id' ki jagah taaki React handle kare */}
      <div ref={widgetRef} style={{ width: "450px" }}></div>
      <Menu />
    </div>
  );
};

export default TopBar;
